    internal static string Get(AppLanguage language, string key)
    {
        if (!Table.TryGetValue(key, out var map))
        {
            return key;
        }

        return map.TryGetValue(language, out var text) ? text : map[AppLanguage.Tr];
    }

    private static Dictionary<AppLanguage, string> Dict(
        string tr, string ar, string en, string es, string ru, string fr) =>
        new()
        {
            [AppLanguage.Tr] = tr,
            [AppLanguage.Ar] = ar,
            [AppLanguage.En] = en,
            [AppLanguage.Es] = es,
            [AppLanguage.Ru] = ru,
            [AppLanguage.Fr] = fr
        };
}
